# Homebrew formula for the AY Inbox CLI. Generated by scripts/build-cli.sh;
# scripts/publish-cli.sh copies it into the ayinbox/homebrew-tap repository.
class Ayinbox < Formula
  desc "AY Inbox from the command line: campaigns, contacts, mailboxes, inbox"
  homepage "https://ayinbox.com"
  version "0.8.0"
  license :cannot_represent

  on_macos do
    on_intel do
      url "https://github.com/ayinbox/ayinbox-cli/releases/download/v0.8.0/ayinbox_darwin_amd64.tar.gz"
      sha256 "bf6496817d5adcee1e41c42bbd352b60f884cbc2f08e041358893fd54b89f3c2"
    end
    on_arm do
      url "https://github.com/ayinbox/ayinbox-cli/releases/download/v0.8.0/ayinbox_darwin_arm64.tar.gz"
      sha256 "a629b72caebdfe22461eb4d24c2a42e0105c6da5c78584e3f4484539f866cf69"
    end
  end

  on_linux do
    on_intel do
      url "https://github.com/ayinbox/ayinbox-cli/releases/download/v0.8.0/ayinbox_linux_amd64.tar.gz"
      sha256 "924b65f559aded9435d72af2cdce35c1bb474ab0a2fb3823176515230eae4281"
    end
    on_arm do
      url "https://github.com/ayinbox/ayinbox-cli/releases/download/v0.8.0/ayinbox_linux_arm64.tar.gz"
      sha256 "126f9cf787d2082550d1c3d3e9236b28688b36116ef9c703d0fb58b3c498e8c0"
    end
  end

  def install
    bin.install "ayinbox"
    bash_completion.install "completions/ayinbox.bash" => "ayinbox"
    zsh_completion.install "completions/ayinbox.zsh" => "_ayinbox"
    fish_completion.install "completions/ayinbox.fish" => "ayinbox.fish"
  end

  test do
    assert_match "ayinbox", shell_output("#{bin}/ayinbox version")
  end
end
